import React, { useState } from "react";

export default function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const [filters, setFilters] = useState({
    publications: true,
    trials: true,
    risk: true
  });

  const toggleFilter = (key) => {
    setFilters((prev) => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handleRun = async () => {
    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          disease,
          intent,
          location
        })
      });

      const result = await res.json();
      setData(result);
    } catch (err) {
      alert("Backend not connected");
    }

    setLoading(false);
  };

  const safeData = data || {
    publications: [],
    clinical_trials: []
  };

  return (
    <div style={container}>

      {/* LEFT PANEL */}
      <div style={left}>
        <h2>Curalink X</h2>

        <input
          placeholder="Filter by disease..."
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={input}
        />

        <h3>Stats</h3>
        <p>📄 Papers: {safeData.publications.length}</p>
        <p>🧪 Trials: {safeData.clinical_trials.length}</p>

        <h3>Insight Filters</h3>

        <label style={filter}>
          <input
            type="checkbox"
            checked={filters.publications}
            onChange={() => toggleFilter("publications")}
          />
          Publications
        </label>

        <label style={filter}>
          <input
            type="checkbox"
            checked={filters.trials}
            onChange={() => toggleFilter("trials")}
          />
          Clinical trials
        </label>

        <label style={filter}>
          <input
            type="checkbox"
            checked={filters.risk}
            onChange={() => toggleFilter("risk")}
          />
          Risk analysis
        </label>
      </div>

      {/* CENTER */}
      <div style={center}>
        <h1>🧠 AI Medical Research Copilot</h1>
        <p style={{ opacity: 0.7 }}>
          Turn complex medical queries into structured insights
        </p>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          style={textarea}
        />

        <button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Send message"}
        </button>

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={input}
        />
      </div>

      {/* RIGHT */}
      <div style={right}>

        {/* SUMMARY */}
        <div style={card}>
          <h3>Dynamic Insights</h3>
          {!data && <p>No data yet</p>}
          {data && <p>{data.summary}</p>}
        </div>

        {/* PAPERS */}
        {filters.publications && (
          <div style={card}>
            <h3>Research papers</h3>
            {safeData.publications.length === 0 && (
              <p>No publication cards available yet.</p>
            )}
            {safeData.publications.map((p, i) => (
              <div key={i} style={item}>
                <strong>{p.title}</strong>
                <p style={meta}>{p.source} • {p.year}</p>
              </div>
            ))}
          </div>
        )}

        {/* TRIALS */}
        {filters.trials && (
          <div style={card}>
            <h3>Clinical trials</h3>
            {safeData.clinical_trials.length === 0 && (
              <p>No clinical trials matched the current filters.</p>
            )}
            {safeData.clinical_trials.map((t, i) => (
              <div key={i} style={item}>
                <strong>{t.title}</strong>
                <p style={meta}>{t.status}</p>
              </div>
            ))}
          </div>
        )}

        {/* RISK */}
        {filters.risk && (
          <div style={card}>
            <h3>Risk analysis</h3>
            {!data && <p>Risk analysis will appear after the first run.</p>}
            {data && (
              <p>
                Risk confidence:{" "}
                {Math.min(90, safeData.publications.length * 10)}%
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* 🎨 STYLES */

const container = {
  display: "flex",
  height: "100vh",
  background: "linear-gradient(135deg,#0f172a,#020617)",
  color: "white"
};

const left = {
  width: "260px",
  padding: "20px",
  background: "#1e293b"
};

const center = {
  flex: 1,
  padding: "20px"
};

const right = {
  width: "380px",
  padding: "20px",
  background: "#1e293b",
  overflowY: "auto"
};

const input = {
  width: "100%",
  padding: "10px",
  marginTop: "10px",
  borderRadius: "8px",
  border: "none"
};

const textarea = {
  width: "100%",
  height: "120px",
  marginTop: "10px",
  padding: "10px",
  borderRadius: "10px"
};

const button = {
  marginTop: "10px",
  padding: "12px",
  width: "100%",
  background: "linear-gradient(90deg,#3b82f6,#8b5cf6)",
  border: "none",
  borderRadius: "10px",
  color: "white",
  fontWeight: "bold",
  cursor: "pointer"
};

const card = {
  background: "#0f172a",
  padding: "15px",
  marginTop: "15px",
  borderRadius: "12px"
};

const item = {
  marginTop: "10px"
};

const meta = {
  fontSize: "12px",
  opacity: 0.7
};

const filter = {
  display: "flex",
  gap: "10px",
  marginTop: "8px"
};
